function preprocess(){return `<div class="content"><div class="section-head"><div><h2>Preprocessing pipeline</h2><p>Normalize, validate and align every evidence source before inference.</p></div><button class="primary" onclick="runPreprocess()">▶ Run preprocessing</button></div><div class="page-grid"><div class="panel detail-card"><div class="pipeline"><div class="pipeline-row done"><div class="step-num">✓</div><div><strong>Raw data intake</strong><span>12 satellite scenes · 18,542 AIS records</span></div><em>COMPLETE</em></div><div class="pipeline-row done"><div class="step-num">✓</div><div><strong>Validation</strong><span>Schema, checksum and coordinate checks</span></div><em>COMPLETE</em></div><div class="pipeline-row done"><div class="step-num">✓</div><div><strong>Cleaning</strong><span>Removed 4.2% duplicate or corrupt AIS points</span></div><em>COMPLETE</em></div><div class="pipeline-row done"><div class="step-num">✓</div><div><strong>Geospatial alignment</strong><span>EPSG:4326 · 10 m raster grid</span></div><em>COMPLETE</em></div><div class="pipeline-row done"><div class="step-num">✓</div><div><strong>Time synchronization</strong><span>Window aligned to 17 Apr 2026 · 14:30 UTC</span></div><em>COMPLETE</em></div><div class="pipeline-row active"><div class="step-num">6</div><div><strong>Processed data package</strong><span>Ready for spill inference</span></div><em>READY</em></div></div></div><div class="panel detail-card"><h3>Processing statistics</h3><div class="stat-line"><span>Satellite images processed</span><strong>12</strong></div><div class="stat-line"><span>AIS records processed</span><strong>18,542</strong></div><div class="stat-line"><span>Missing AIS records</span><strong style="color:var(--amber)">4.2%</strong></div><div class="stat-line"><span>Ocean data records</span><strong>1,250</strong></div><div class="stat-line"><span>Processing time</span><strong>00:02:18</strong></div></div></div></div>`}
function detection(){return `<div class="content"><div class="section-head"><div><h2>Oil spill detection</h2><p>Segmentation result from a simulated SAR inference pipeline.</p></div><button class="primary" onclick="toast('Demo detection already complete')">▶ Run detection</button></div><div class="page-grid"><div class="panel"><div class="panel-head"><span class="panel-title">Scene comparison</span><span class="tag amber">DEMO / SIMULATION</span></div><div class="map-canvas" style="height:350px"><div class="map-label" style="top:22%;left:10%">SENTINEL-1 · VV POLARIZATION</div><div style="position:absolute;left:35%;top:30%;width:200px;height:105px;background:#1c3d3a;opacity:.8;transform:rotate(-18deg);clip-path:polygon(7% 25%,28% 5%,76% 12%,100% 45%,82% 79%,44% 100%,13% 76%);box-shadow:0 0 35px #f0b45b66"></div><div class="pin spill" style="left:51%;top:43%"></div><span class="map-label" style="left:44%;top:75%;color:var(--amber)">SEGMENTED DARK-FORMATION</span></div></div><div class="panel detail-card"><h3>Spill detected</h3><p>Irregular low-backscatter formation is consistent with a surface oil-like anomaly. This prototype uses a simulated result for demonstration.</p><div class="stat-line"><span>Estimated area</span><strong>18.6 km²</strong></div><div class="stat-line"><span>Confidence</span><strong style="color:var(--cyan)">94.2%</strong></div><div class="stat-line"><span>Centroid</span><strong>12.4821°N, 78.2145°E</strong></div><div class="stat-line"><span>Boundary points</span><strong>148</strong></div><div class="stat-line"><span>Uncertainty radius</span><strong>±1.8 km</strong></div></div></div><div class="panel classification-panel"><div class="panel-head"><span class="panel-title">🛰️ Spill Classification / Look-Alike Detection</span><span class="tag classification-pass">✓ LOOK-ALIKE CHECK: PASSED</span></div><div class="classification-intro"><div class="classification-icon">AI</div><div><strong>Detected Region Classification</strong><p>The detected dark region was evaluated against common oil-spill look-alike patterns such as natural ocean phenomena and other dark surface features.</p></div><div class="classification-confidence"><strong>94%</strong><span>OIL SPILL CONFIDENCE</span></div></div><div class="classification-results"><div class="classification-result oil"><div><span>🛢️ Oil Spill</span><strong>94%</strong></div><i><em style="width:94%"></em></i></div><div class="classification-result natural"><div><span>🌊 Natural Phenomenon</span><strong>3%</strong></div><i><em style="width:3%"></em></i></div><div class="classification-result other"><div><span>❓ Other</span><strong>3%</strong></div><i><em style="width:3%"></em></i></div></div><div class="classification-flow"><span>DARK REGION DETECTED</span><b>→</b><span>AI CLASSIFICATION</span><b>→</b><strong>DETECTION ACCEPTED</strong></div></div></div>`}
function drift(){return `<div class="content"><div class="section-head"><div><h2>Drift analysis</h2><p>Backtracking surface transport under simulated current and wind conditions.</p></div><button class="outline" onclick="toast('Forecast settings saved')">⚙ Forecast settings</button></div>${map()}<div class="panel detail-card" style="margin-top:18px"><div class="timeline"><span class="time-point">T−24h</span><span class="time-point">T−18h</span><span class="time-point">T−12h</span><span class="time-point">T−6h</span><span class="time-point">T0</span></div><div class="stats-list" style="display:grid;grid-template-columns:repeat(4,1fr);gap:18px"><div class="stat-line"><span>Current</span><strong>1.8 kn · NE</strong></div><div class="stat-line"><span>Wind</span><strong>12 kn · WNW</strong></div><div class="stat-line"><span>Forecast horizon</span><strong>24 hours</strong></div><div class="stat-line"><span>Path uncertainty</span><strong>±6.4 km</strong></div></div></div></div>`}
