function trajectoryGraph(){const colors=['#4e9dff','#f6c76a','#67e5ae','#ff7188','#b58cff'];const styles=['solid','dashed','dotted','dashdot','longdash'];const paths=['M90 270 C170 250 230 210 300 205 S430 225 510 160 S650 105 735 88','M78 305 C155 280 220 248 275 220 S390 180 460 190 S620 155 735 125','M110 115 C185 140 225 178 300 190 S420 205 505 185 S650 150 735 115','M70 210 C150 205 210 190 280 170 S395 145 470 165 S600 205 735 155','M100 335 C190 315 235 270 320 250 S455 220 540 205 S660 185 735 150'];return `<div class="trajectory-wrap"><div class="trajectory-heading"><div><h3>Vessel Trajectories vs. Spill Drift</h3><p>Trajectory comparison of the 5 correlated vessels with the reconstructed oil-spill drift path.</p></div><span class="trajectory-note">Correlation supports assessment; it does not prove responsibility.</span></div><div class="trajectory-plot"><svg viewBox="0 0 800 390" role="img" aria-label="Vessel trajectories compared with reconstructed spill drift"><defs><marker id="trajectory-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M 0 0 L 10 5 L 0 10 z" fill="#0d9ca3"/></marker><marker id="vessel-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M 0 0 L 10 5 L 0 10 z" fill="#d8f5f5"/></marker></defs><g class="trajectory-grid"><path d="M70 55H755 M70 115H755 M70 175H755 M70 235H755 M70 295H755 M70 355H755 M70 55V355 M207 55V355 M344 55V355 M481 55V355 M618 55V355 M755 55V355"/></g><text x="70" y="378">76°E</text><text x="235" y="378">77°E</text><text x="400" y="378">78°E</text><text x="565" y="378">79°E</text><text x="720" y="378">80°E</text><text x="22" y="62">15°N</text><text x="22" y="182">13°N</text><text x="22" y="302">11°N</text><text x="360" y="388">Longitude / East-West Position</text><text transform="translate(12 260) rotate(-90)">Latitude / North-South Position</text>${paths.map((path,index)=>`<path class="trajectory-line vessel-path ${styles[index]}" d="${path}" stroke="${colors[index]}" marker-end="url(#vessel-arrow)"/><circle class="trajectory-arrow-dot" cx="${[330,305,335,315,350][index]}" cy="${[205,220,193,170,248][index]}" r="3" fill="${colors[index]}"/>`).join('')}<path class="trajectory-line spill-drift-path" d="M135 305 C235 290 315 270 390 245 S510 205 610 155 S690 125 735 105" marker-end="url(#trajectory-arrow)"/><circle class="source-marker" cx="135" cy="305" r="9"/><circle class="spill-marker" cx="735" cy="105" r="9"/><text class="plot-label source-label" x="98" y="330">PROBABLE SOURCE</text><text class="plot-label spill-label" x="650" y="88">DETECTED SPILL</text></svg></div><div class="trajectory-legend">${vessels.map((v,index)=>`<span><i style="--legend-color:${colors[index]}" class="legend-line ${styles[index]}"></i>Vessel ${index+1} · ${v.name}</span>`).join('')}<span><i class="legend-line spill-legend"></i>Spill Drift</span></div></div>`}
function ais(){return `<div class="content"><div class="section-head"><div><h2>AIS vessel correlation</h2><p>Vessels intersecting the source region and reconstructed time window.</p></div><button class="outline" onclick="toast('AIS data exported as CSV')">⇩ Export CSV</button></div><div class="panel trajectory-panel">${trajectoryGraph()}</div><div class="panel" style="margin-top:18px"><div class="panel-head"><span class="panel-title">Correlated vessels · 5 candidates</span><span class="panel-meta">RADIUS 60 KM · WINDOW ±12 H</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>RANK</th><th>VESSEL</th><th>TYPE</th><th>DISTANCE</th><th>TIME DIFFERENCE</th><th>TRAJECTORY</th><th>SCORE</th></tr></thead><tbody>${vessels.map((v,i)=>`<tr onclick="selectVessel(${i})" style="cursor:pointer"><td><strong style="color:${i===0?'var(--amber)':'var(--muted)'}">0${v.rank}</strong></td><td><strong>${v.name}</strong><div class="tiny">MMSI ${v.mmsi} · IMO ${v.imo}</div></td><td>${v.type}</td><td>${v.distance}</td><td>${v.delta}</td><td><span class="tag ${i<2?'':'amber'}">${v.trajectory}</span></td><td><strong style="color:var(--cyan)">${v.score}</strong></td></tr>`).join('')}</tbody></table></div></div></div>`}
function ranking(){return `<div class="content"><div class="section-head"><div><h2>Explainable candidate ranking</h2><p>Four evidence dimensions combine into a candidate likelihood score.</p></div><span class="tag amber">NOT PROOF OF RESPONSIBILITY</span></div><div class="page-grid"><div class="panel"><div class="panel-head"><span class="panel-title">Candidate likelihood</span><span class="panel-meta">WEIGHTED MODEL</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>#</th><th>VESSEL</th><th>SPATIAL</th><th>TEMPORAL</th><th>TRAJECTORY</th><th>DRIFT</th><th>OVERALL</th></tr></thead><tbody>${vessels.map((v,i)=>`<tr><td>${v.rank}</td><td><strong>${v.name}</strong></td><td>${[92,84,73,61,54][i]}%</td><td>${[88,86,77,64,51][i]}%</td><td>${v.trajectory}</td><td>${[85,80,71,60,48][i]}%</td><td><strong style="color:var(--cyan)">${v.score}</strong></td></tr>`).join('')}</tbody></table></div></div><div class="panel detail-card"><h3>Why MV Ocean Star leads</h3><p>Its recorded trajectory passed close to the estimated source region during the reconstructed spill window, with heading and speed consistent with the modeled drift.</p><div class="stat-line"><span>Spatial consistency</span><strong>92%</strong></div><div class="stat-line"><span>Temporal consistency</span><strong>88%</strong></div><div class="stat-line"><span>Trajectory consistency</span><strong>94%</strong></div><div class="stat-line"><span>Drift consistency</span><strong>85%</strong></div><div class="progress"><span style="width:92.4%"></span></div></div></div></div>`}
function evidence(){return `<div class="content"><div class="section-head"><div><h2>Evidence graph</h2><p>Trace every conclusion back to a supporting observation.</p></div><button class="outline" onclick="toast('Evidence chain copied')">⛓ Copy chain</button></div><div class="panel graph"><svg viewBox="0 0 900 360"><path d="M150 180 L300 90 L450 180 L650 90 M450 180 L650 280 L760 210" fill="none" stroke="#39676b" stroke-width="1.5" stroke-dasharray="4 5"/></svg><div class="graph-node n1" onclick="toast('Satellite evidence: Sentinel-1 pass 0417')"><strong>Satellite image</strong><span>Sentinel-1 pass</span></div><div class="graph-node n2" onclick="toast('Spill evidence: 18.6 km² segmented area')"><strong>Detected spill</strong><span>94.2% confidence</span></div><div class="graph-node n3" onclick="toast('Drift evidence: 24h backtracking')"><strong>Drift reconstruction</strong><span>Current + wind</span></div><div class="graph-node n4" onclick="toast('Source evidence: 12.4821°N, 78.2145°E')"><strong>Estimated source</strong><span>±6.4 km region</span></div><div class="graph-node n5" onclick="toast('AIS evidence: MV Ocean Star within 8.2 km')"><strong>AIS vessel</strong><span>MV Ocean Star</span></div><div class="graph-node n6" onclick="toast('Ranking evidence: overall score 92.4%')"><strong>Candidate score</strong><span>92.4% likelihood</span></div></div><div class="evidence-list" style="margin-top:18px"><div class="evidence-item"><div class="evidence-icon">◈</div><div><strong>Satellite evidence</strong><span>Low-backscatter formation segmented at 12.4821°N, 78.2145°E with 94.2% model confidence.</span></div></div><div class="evidence-item"><div class="evidence-icon">↝</div><div><strong>Drift evidence</strong><span>Backtracking under 1.8 kn northeast current and 12 kn WNW wind points to the probable source region.</span></div></div><div class="evidence-item"><div class="evidence-icon">≋</div><div><strong>AIS evidence</strong><span>MV Ocean Star was within 8.2 km of the source region at 16 Apr, 22:44 UTC.</span></div></div></div></div>`}
function report(){return `<div class="content"><div class="section-head"><div><h2>Investigation report</h2><p>Prepared for investigator review · Evidence package OE-26-0417</p></div><button class="primary" onclick="window.print()">⇩ Export / print PDF</button></div><div class="report"><div class="eyebrow">OCEANEYE / MARINE OIL-SPILL INVESTIGATION REPORT</div><h2>Bay of Bengal spill event</h2><p>Investigation ID OE-26-0417 · Generated 17 Apr 2026, 14:42 UTC · Demo environment</p><div class="report-grid"><div><span>SPILL LOCATION</span><strong>12.4821°N, 78.2145°E</strong></div><div><span>ESTIMATED AREA</span><strong>18.6 km²</strong></div><div><span>DETECTION CONFIDENCE</span><strong>94.2%</strong></div><div><span>PROBABLE SOURCE</span><strong>12.4821°N, 78.2145°E ±6.4 km</strong></div><div><span>LEADING CANDIDATE</span><strong>MV Ocean Star · 92.4%</strong></div><div><span>VESSELS CORRELATED</span><strong>5 of 8 nearby</strong></div></div><section class="report-section"><h3>Executive Summary</h3><p>This investigation examines a simulated oil-spill event detected on 17 Apr 2026 at 12.4821°N, 78.2145°E. The estimated area is 18.6 km² with 94.2% detection confidence. Environmental reconstruction places the probable source at the same region with ±6.4 km uncertainty; five correlated vessels were assessed, led by MV Ocean Star at 92.4% overall compatibility.</p></section><section class="report-section"><h3>Spill Detection Information</h3><div class="report-stat-grid"><div><span>Classification</span><strong>Oil spill · 94%</strong></div><div><span>Boundary points</span><strong>148</strong></div><div><span>Look-alike check</span><strong>Passed</strong></div><div><span>Uncertainty radius</span><strong>±1.8 km</strong></div></div></section><section class="report-section"><h3>Environmental Conditions &amp; Drift Analysis</h3><div class="report-stat-grid"><div><span>Ocean current</span><strong>1.8 kn · NE</strong></div><div><span>Wind conditions</span><strong>12 kn · WNW</strong></div><div><span>Analysis horizon</span><strong>24 hours</strong></div><div><span>Drift uncertainty</span><strong>±6.4 km</strong></div></div><p>Current and wind conditions were used to reconstruct the probable movement of the surface anomaly backward through the 24-hour analysis window. The resulting drift path supports a probable source region, subject to the stated uncertainty.</p></section><section class="report-section report-trajectory"><h3>Vessel Trajectories vs. Spill Drift</h3>${trajectoryGraph()}<p>Trajectory comparison provides supporting spatial and temporal evidence for assessing which vessel movement is most consistent with the estimated spill source and reconstructed drift.</p></section><section class="report-section"><h3>Existing Candidate &amp; Vessel Information</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>RANK</th><th>VESSEL</th><th>TYPE</th><th>DISTANCE</th><th>TIME DIFFERENCE</th><th>TRAJECTORY</th><th>SCORE</th></tr></thead><tbody>${vessels.map(v=>`<tr><td>${v.rank}</td><td><strong>${v.name}</strong></td><td>${v.type}</td><td>${v.distance}</td><td>${v.delta}</td><td>${v.trajectory}</td><td><strong>${v.score}</strong></td></tr>`).join('')}</tbody></table></div></section><section class="report-section"><h3>Evidence Chain &amp; Final Assessment</h3><div class="evidence-chain"><span>Satellite Observation</span><b>→</b><span>Spill Detection</span><b>→</b><span>Environmental Analysis</span><b>→</b><span>Drift Reconstruction</span><b>→</b><span>Probable Source</span><b>→</b><span>AIS Correlation</span><b>→</b><span>Vessel Trajectory</span><b>→</b><span>Candidate Ranking</span></div><p>Satellite observation identifies the low-backscatter anomaly; spill detection quantifies and classifies it; environmental analysis and drift reconstruction estimate movement and source; AIS correlation supplies nearby vessel tracks; trajectory comparison and ranking organize candidate compatibility.</p><h4>Final Assessment</h4><p>The identified vessel is the highest-ranked candidate based on the available spatial, temporal, drift, trajectory and AIS evidence. This is a candidate assessment, not a definitive attribution.</p><div class="report-stat-grid"><div><span>Spatial compatibility</span><strong>92%</strong></div><div><span>Temporal compatibility</span><strong>88%</strong></div><div><span>Drift compatibility</span><strong>85%</strong></div><div><span>Trajectory consistency</span><strong>94%</strong></div><div><span>AIS reliability</span><strong>90%</strong></div><div><span>Behavioural indicator</span><strong>78%</strong></div></div></section><section class="report-section"><h3>Recommended Investigator Actions</h3><ul class="report-actions"><li>Review the leading candidate's detailed AIS trajectory.</li><li>Verify the vessel's voyage and movement records.</li><li>Cross-check the estimated source time and location.</li><li>Compare additional satellite observations where available.</li><li>Validate the environmental and drift conditions.</li><li>Conduct further investigation before final attribution decisions.</li></ul><h4>Limitations &amp; Confidence</h4><p>AIS gaps or incomplete coverage, satellite and environmental data limitations, drift-model uncertainty, possible satellite look-alike patterns, and uncertainty in the estimated source region may affect the result. Evidence-based findings should be distinguished from uncertainty and independently corroborated.</p></section><div class="notice"><strong>Limitations and uncertainty.</strong> This analysis indicates candidate likelihood, not proof of responsibility. Independent corroboration is required.</div></div></div>`}
function map(){return `<div class="panel map-panel"><div class="panel-head"><span class="panel-title">Operational picture · World map</span><span class="panel-meta">17 APR 2026 · 14:30 UTC · 12.48°N 78.21°E</span></div><div class="world-map" data-zoom="1"><div class="world-map-content"><div class="world-grid"></div><div class="continent asia"></div><div class="continent africa"></div><div class="continent europe"></div><div class="continent australia"></div><div class="map-region source-region"></div><svg class="world-routes" viewBox="0 0 1000 470" preserveAspectRatio="none"><path class="route-observed" d="M605 292 C650 270 690 250 728 218 S790 190 830 172"/><path class="route-drift" d="M606 293 C570 284 535 296 492 332"/><path class="route-vessel" d="M606 293 C650 278 684 252 720 220"/><path class="route-vessel route-vessel-2" d="M606 293 C660 310 720 300 780 278"/></svg><div class="world-pin spill-pin">SPILL<div>18.6 km²</div></div><div class="world-pin source-pin">SOURCE<div>87% region</div></div><div class="world-vessel vessel-one">01</div><div class="world-vessel vessel-two">02</div><div class="world-vessel vessel-three">03</div><div class="world-vessel vessel-four">04</div><div class="world-vessel vessel-five">05</div><span class="world-label label-india">INDIA</span><span class="world-label label-bengal">BAY OF BENGAL</span><span class="world-label label-arabian">ARABIAN SEA</span></div><div class="world-hud"><span>WORLD MAP · AIS + DRIFT</span><strong>12.4821°N · 78.2145°E</strong><small>SPILL REGION LOCKED · 94.2%</small></div><div class="world-controls"><button type="button" onclick="worldMapZoom(-.2)" title="Zoom out">−</button><button type="button" onclick="worldMapFocus()" title="Focus spill">⌖</button><button type="button" onclick="worldMapZoom(.2)" title="Zoom in">＋</button></div><div class="world-legend"><span><i class="legend-spill"></i>DETECTED SPILL</span><span><i class="legend-vessel"></i>AIS VESSELS</span><span><i class="legend-drift"></i>DRIFT / TRAJECTORY</span></div></div></div>`}
function source(){return `<div class="content"><div class="section-head"><div><h2>Source estimation</h2><p>Probable origin region inferred by reversing the modeled transport path.</p></div><span class="tag amber">ANALYTICAL ESTIMATE</span></div><div class="page-grid">${map()}<div class="panel detail-card"><div class="eyebrow">PROBABLE SOURCE REGION</div><h2 style="font-size:28px;margin:10px 0;color:var(--blue)">12.4821°N</h2><h2 style="font-size:28px;margin:0 0 14px;color:var(--blue)">78.2145°E</h2><div class="stat-line"><span>Estimated source time</span><strong>16 Apr · 20:30 UTC</strong></div><div class="stat-line"><span>Source confidence</span><strong style="color:var(--teal)">87%</strong></div><div class="stat-line"><span>Region radius</span><strong>±6.4 km</strong></div><p class="notice" style="margin-top:18px">This region is a probabilistic reconstruction. It should be corroborated with operational records and additional imagery.</p></div></div><div class="panel heatmap-panel"><div class="panel-head"><span class="panel-title">Source probability heatmap</span><span class="panel-meta">BACKTRACKED PROBABILITY FIELD</span></div><div class="probability-map"><div class="probability-grid"></div><div class="probability-blob blob-outer"></div><div class="probability-blob blob-mid"></div><div class="probability-blob blob-core"></div><div class="probability-point"></div><span class="heat-label">12.4821°N · 78.2145°E</span></div><div class="probability-legend"><span>LOW</span><i class="heat-low"></i><i class="heat-mid"></i><i class="heat-high"></i><span>HIGH</span></div></div></div>`}
function ranking(){const v=vessels[state.selectedVessel];return `<div class="content"><div class="section-head"><div><h2>Explainable candidate ranking</h2><p>Evidence dimensions combine into a candidate likelihood score.</p></div><span class="tag amber">NOT PROOF OF RESPONSIBILITY</span></div><div class="page-grid"><div class="panel"><div class="panel-head"><span class="panel-title">Candidate likelihood</span><span class="panel-meta">WEIGHTED MODEL</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>#</th><th>VESSEL</th><th>SPATIAL</th><th>TEMPORAL</th><th>TRAJECTORY</th><th>DRIFT</th><th>OVERALL</th></tr></thead><tbody>${vessels.map((candidate,i)=>`<tr onclick="selectVessel(${i});render()" style="cursor:pointer"><td>${candidate.rank}</td><td><strong>${candidate.name}</strong></td><td>${[92,84,73,61,54][i]}%</td><td>${[88,86,77,64,51][i]}%</td><td>${candidate.trajectory}</td><td>${[85,80,71,60,48][i]}%</td><td><strong style="color:var(--blue)">${candidate.score}</strong></td></tr>`).join('')}</tbody></table></div></div><div class="panel detail-card why-vessel"><h3>Why This Vessel?</h3><div class="overall-score"><strong>${v.score}</strong><span>OVERALL SCORE · RANK ${v.rank}</span></div><p>${v.name} ranks highly because its AIS track passed within ${v.distance} of the reconstructed source during the compatible time window, while its movement aligned with the modeled drift.</p><div class="evidence-bars"><div><span>Source proximity</span><b>92%</b><i><em style="width:92%"></em></i></div><div><span>Time compatibility</span><b>88%</b><i><em style="width:88%"></em></i></div><div><span>Drift compatibility</span><b>85%</b><i><em style="width:85%"></em></i></div><div><span>Trajectory consistency</span><b>94%</b><i><em style="width:94%"></em></i></div><div><span>AIS reliability</span><b>90%</b><i><em style="width:90%"></em></i></div><div><span>Behaviour anomaly</span><b>78%</b><i><em style="width:78%"></em></i></div></div></div></div><div class="page-grid analysis-grid"><div class="panel detail-card"><h3>Vessel Behaviour Anomaly</h3><p>Movement signals that differ from the vessel's expected passage profile near the estimated source.</p><div class="anomaly-level"><span>Anomaly level</span><strong>Moderate</strong></div><div class="anomaly-list"><div><b>Speed changes</b><span>11.8 → 7.1 kn over 34 min</span></div><div><b>Course deviations</b><span>18° deviation toward source region</span></div><div><b>Loitering</b><span>42 min below 4 kn</span></div><div><b>AIS gaps</b><span>9 min gap during source window</span></div><div><b>Near source movement</b><span>Unusual maneuver within 8.2 km</span></div></div></div><div class="panel detail-card"><h3>What-if Spill Simulation</h3><p>Compare the modeled outcome if the selected vessel were the source.</p><label class="select-label" for="simulation-vessel">Candidate vessel</label><select id="simulation-vessel" onchange="selectSimulationVessel(this.value)">${vessels.map((candidate,i)=>`<option value="${i}" ${i===state.selectedVessel?'selected':''}>${candidate.name}</option>`).join('')}</select><div class="simulation-map"><svg viewBox="0 0 500 180" preserveAspectRatio="none"><path class="sim-observed" d="M35 145 C130 125 195 115 260 82 S375 62 460 32"/><path class="simulated-path" d="M35 145 C120 150 188 126 248 96 S365 92 460 54"/><circle cx="35" cy="145" r="6"/><circle cx="460" cy="32" r="6"/></svg><div><span class="sim-key observed-key">Observed / reconstructed</span><span class="sim-key simulated-key">Simulated from candidate</span></div></div><div class="compatibility"><span>Trajectory compatibility</span><strong>${v.trajectory}</strong></div></div></div></div>`}
function worldMapZoom(delta){const stage=document.querySelector('.world-map');if(!stage)return;const zoom=Math.max(.8,Math.min(2.2,Number(stage.dataset.zoom)+delta));stage.dataset.zoom=zoom;stage.querySelector('.world-map-content').style.transform=`scale(${zoom})`}
function worldMapFocus(){const stage=document.querySelector('.world-map');if(!stage)return;stage.dataset.zoom='1.55';stage.querySelector('.world-map-content').style.transform='scale(1.55)';toast('Spill region focused · 12.4821°N 78.2145°E')}
function initWorldMap(){document.querySelectorAll('.world-map').forEach(stage=>{let dragging=false,lastX=0,lastY=0,x=0,y=0;stage.addEventListener('pointerdown',event=>{dragging=true;lastX=event.clientX;lastY=event.clientY;stage.setPointerCapture(event.pointerId)});stage.addEventListener('pointermove',event=>{if(!dragging)return;x+=event.clientX-lastX;y+=event.clientY-lastY;stage.querySelector('.world-map-content').style.transform=`translate(${x}px,${y}px) scale(${stage.dataset.zoom})`;lastX=event.clientX;lastY=event.clientY});stage.addEventListener('pointerup',()=>dragging=false);stage.addEventListener('wheel',event=>{event.preventDefault();worldMapZoom(event.deltaY>0?-.08:.08)},{passive:false})})}
function legacyGlobeMap(){return `<div class="panel map-panel"><div class="panel-head"><span class="panel-title">Operational picture</span><span class="panel-meta">17 APR 2026 · 14:30 UTC · 12.48°N 78.21°E</span></div><div class="globe-stage" data-zoom="1"><div class="globe-orbit orbit-a"></div><div class="globe-orbit orbit-b"></div><div class="globe"><div class="globe-lat lat-a"></div><div class="globe-lat lat-b"></div><div class="globe-land land-a"></div><div class="globe-land land-b"></div><div class="globe-spill"></div><div class="globe-grid"></div><span class="globe-place-label place-india">INDIA</span><span class="globe-place-label place-bengal">BAY OF BENGAL</span><span class="globe-place-label place-spill">SPILL · 12.4821°N</span></div><div class="globe-hud"><span>LIVE SAR SURFACE</span><strong>12.4821°N · 78.2145°E</strong><small>SPILL REGION LOCKED · 94.2%</small></div><div class="globe-controls"><button type="button" onclick="globeZoom(-.2)" title="Zoom out">−</button><button type="button" onclick="globeFocus()" title="Focus spill">⌖</button><button type="button" onclick="globeZoom(.2)" title="Zoom in">＋</button></div><div class="globe-legend"><span><i class="globe-dot spill-dot"></i>DETECTED SPILL · 18.6 KM²</span><span><i class="globe-dot vessel-dot"></i>AIS TRACKS</span><span><i class="globe-line"></i>DRIFT VECTOR</span></div></div></div>`}
function evidence(){return `<div class="content"><div class="section-head"><div><h2>Evidence graph</h2><p>Trace every conclusion back to a supporting observation.</p></div><button class="outline" onclick="toast('Evidence chain copied')">⛓ Copy chain</button></div><div class="panel evidence-network"><div class="network-toolbar"><span>INVESTIGATION NETWORK / 6 EVIDENCE STATES</span><span><b>94.2%</b> STRONGEST PATH</span></div><div class="network-viewport" onwheel="networkZoom(event)" onpointerdown="networkPanStart(event)"><svg class="network-lines" viewBox="0 0 900 520" aria-hidden="true"><defs><marker id="arrow-cyan" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#61e6ff"/></marker><filter id="network-glow"><feGaussianBlur stdDeviation="3" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><path class="network-link strong" d="M142 250 C205 100 310 85 383 168 S505 312 601 250 S728 190 790 120" marker-end="url(#arrow-cyan)"/><path class="network-link" d="M142 250 C250 405 330 445 428 347 S540 254 601 250" marker-end="url(#arrow-cyan)"/><path class="network-link" d="M383 168 C450 70 520 65 601 110" marker-end="url(#arrow-cyan)"/><path class="network-link faint-link" d="M601 250 C670 350 730 380 790 330" marker-end="url(#arrow-cyan)"/></svg><button class="network-node satellite" onclick="selectEvidence(this,'Satellite evidence: Sentinel-1 pass 0417')"><i>01</i><strong>Satellite evidence</strong><span>Sentinel-1 pass 0417</span><b>94.2%</b></button><button class="network-node spill" onclick="selectEvidence(this,'Spill evidence: 18.6 km² segmented area')"><i>02</i><strong>Detected oil spill</strong><span>18.6 km² anomaly</span><b>94.2%</b></button><button class="network-node drift" onclick="selectEvidence(this,'Drift evidence: 24h backtracking')"><i>03</i><strong>Drift analysis</strong><span>Current + wind field</span><b>87.0%</b></button><button class="network-node source" onclick="selectEvidence(this,'Source evidence: 12.4821°N, 78.2145°E')"><i>04</i><strong>Probable source</strong><span>±6.4 km region</span><b>87.0%</b></button><button class="network-node ais" onclick="selectEvidence(this,'AIS evidence: MV Ocean Star within 8.2 km')"><i>05</i><strong>AIS movement</strong><span>Reconstructed track</span><b>92.4%</b></button><button class="network-node candidate" onclick="selectEvidence(this,'Ranking evidence: overall score 92.4%')"><i>06</i><strong>Candidate vessel</strong><span>MV Ocean Star</span><b>92.4%</b></button><div class="network-axis">OBSERVATION <span>→</span> INFERENCE <span>→</span> ATTRIBUTION</div></div><div class="network-detail" id="network-detail"><span>SELECTED EVIDENCE</span><strong>MV Ocean Star · 92.4% likelihood</strong><p>Click any evidence state to inspect the supporting observation.</p></div></div><div class="evidence-list" style="margin-top:18px"><div class="evidence-item"><div class="evidence-icon">◈</div><div><strong>Satellite evidence</strong><span>Low-backscatter formation segmented at 12.4821°N, 78.2145°E with 94.2% model confidence.</span></div></div><div class="evidence-item"><div class="evidence-icon">↝</div><div><strong>Drift evidence</strong><span>Backtracking under 1.8 kn northeast current and 12 kn WNW wind points to the probable source region.</span></div></div><div class="evidence-item"><div class="evidence-icon">≋</div><div><strong>AIS evidence</strong><span>MV Ocean Star was within 8.2 km of the estimated source during the reconstructed window.</span></div></div></div></div>`}
function evidencePopup(node){const item=currentInvestigation();const type=node.classList.contains('satellite')?'Satellite Imagery':node.classList.contains('spill')?'Detected Oil Spill':node.classList.contains('drift')?'Drift Analysis':node.classList.contains('source')?'Probable Source Region':node.classList.contains('ais')?'AIS Vessel Movement':'Candidate Vessel';const vessel=item.vessels[0];const details={
 'Satellite Imagery':[['Acquisition date/time',item.date],['Satellite / sensor','Sentinel-1 · SAR'],['Location',item.location],['Evidence status','Validated'],['Confidence',item.confidence]],
 'Detected Oil Spill':[['Spill area',item.area],['Location',item.location],['Detection confidence',item.confidence],['Classification','Oil spill'],['Look-alike check',item.lookalikeResult]],
 'Drift Analysis':[['Direction / conditions',item.conditions],['Drift distance',item.driftDistance],['Time window',item.driftWindow],['Starting location',item.location],['Drift status',item.drift]],
 'Probable Source Region':[['Estimated source location',item.source],['Source confidence',item.sourceConfidence],['Estimated time window',item.sourceTime],['Region uncertainty',item.uncertainty]],
 'AIS Vessel Movement':[['Vessel name',vessel.name],['IMO number',vessel.imo],['Distance from spill',vessel.distance],['AIS correlation',item.ais],['Track status','Correlated']],
 'Candidate Vessel':[['Vessel name',vessel.name],['IMO number',vessel.imo],['Overall score',item.candidateScore],['Spatial / temporal','92% / 88%'],['Drift consistency',vessel.trajectory],['Candidate status',vessel.match]]}[type];return `<div class="evidence-popup-head"><span>SELECTED EVIDENCE</span><button type="button" class="evidence-popup-close" onclick="closeEvidence(event)" aria-label="Close evidence details">×</button></div><h3>${type}</h3><div class="evidence-popup-fields">${details.map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join('')}</div>`}
function closeEvidence(event){event.stopPropagation();const popup=document.querySelector('.evidence-popup');if(popup)popup.classList.remove('open');document.querySelectorAll('.network-node').forEach(item=>item.classList.remove('selected'))}
function selectEvidence(node,text){document.querySelectorAll('.network-node').forEach(item=>item.classList.remove('selected'));node.classList.add('selected');let popup=document.querySelector('.evidence-popup');if(!popup){popup=document.createElement('aside');popup.className='evidence-popup';document.querySelector('.evidence-network')?.appendChild(popup)}popup.innerHTML=evidencePopup(node);popup.classList.add('open');const detail=document.getElementById('network-detail');if(detail)detail.innerHTML=`<span>SELECTED EVIDENCE</span><strong>${node.querySelector('strong').textContent} · ${node.querySelector('b').textContent} confidence</strong><p>${text}</p>`;toast(text)}
function globeZoom(delta){const stage=document.querySelector('.globe-stage');if(!stage)return;const zoom=Math.max(.82,Math.min(1.8,Number(stage.dataset.zoom)+delta));stage.dataset.zoom=zoom;stage.style.setProperty('--globe-scale',zoom)}
function globeFocus(){const stage=document.querySelector('.globe-stage');if(!stage)return;stage.dataset.zoom='1.8';stage.style.setProperty('--globe-scale','1.8');toast('Spill region focused · 12.4821°N 78.2145°E')}
function initGlobe(){const stage=document.querySelector('.globe-stage');if(!stage)return;const globe=stage.querySelector('.globe');let dragging=false,lastX=0,lastY=0,velocityX=0,velocityY=0,animationFrame=0;const applyRotation=()=>{const longitude=Number(globe.dataset.rotationY||0),latitude=Number(globe.dataset.rotationX||0);globe.style.setProperty('--globe-texture-x',`${-(longitude%360)/3.6}%`);globe.style.setProperty('--globe-texture-y',`${Math.max(-18,Math.min(18,-(latitude%180)/5))}%`)};const stopInertia=()=>{if(animationFrame)cancelAnimationFrame(animationFrame);animationFrame=0};const inertia=()=>{if(dragging||Math.abs(velocityX)+Math.abs(velocityY)<.02){animationFrame=0;return}globe.dataset.rotationY=Number(globe.dataset.rotationY||0)+velocityX;globe.dataset.rotationX=Number(globe.dataset.rotationX||0)+velocityY;velocityX*=.94;velocityY*=.94;applyRotation();animationFrame=requestAnimationFrame(inertia)};stage.addEventListener('pointerdown',event=>{stopInertia();dragging=true;lastX=event.clientX;lastY=event.clientY;try{stage.setPointerCapture(event.pointerId)}catch{}globe.classList.add('is-dragging')});stage.addEventListener('pointermove',event=>{if(!dragging)return;const deltaX=event.clientX-lastX,deltaY=event.clientY-lastY;velocityX=deltaX*.35;velocityY=-deltaY*.35;globe.dataset.rotationY=Number(globe.dataset.rotationY||0)+velocityX;globe.dataset.rotationX=Number(globe.dataset.rotationX||0)+velocityY;applyRotation();lastX=event.clientX;lastY=event.clientY});const release=event=>{if(!dragging)return;dragging=false;globe.classList.remove('is-dragging');if(event.pointerId!==undefined&&stage.hasPointerCapture(event.pointerId))stage.releasePointerCapture(event.pointerId);animationFrame=requestAnimationFrame(inertia)};stage.addEventListener('pointerup',release);stage.addEventListener('pointercancel',release);stage.addEventListener('wheel',event=>{event.preventDefault();globeZoom(event.deltaY>0?-.08:.08)},{passive:false});applyRotation()}
function initGlobeControls(){document.querySelectorAll('.globe-stage').forEach(stage=>{const controls=stage.querySelectorAll('.globe-controls button');if(controls.length!==3)return;controls[0].onclick=()=>globeZoom(-.2);controls[1].onclick=()=>globeFocus();controls[2].onclick=()=>globeZoom(.2)})}
function networkZoom(event){event.preventDefault();const viewport=event.currentTarget;const scale=Math.max(.75,Math.min(1.35,(Number(viewport.dataset.scale)||1)+(event.deltaY>0?-.08:.08)));viewport.dataset.scale=scale;viewport.style.setProperty('--network-scale',scale)}
function networkPanStart(event){const viewport=event.currentTarget;const startX=event.clientX;const startY=event.clientY;const x=Number(viewport.dataset.x)||0;const y=Number(viewport.dataset.y)||0;const move=moveEvent=>{viewport.style.setProperty('--network-x',`${x+move.clientX-startX}px`);viewport.style.setProperty('--network-y',`${y+move.clientY-startY}px`)};const stop=()=>{viewport.dataset.x=viewport.style.getPropertyValue('--network-x').replace('px','')||x;viewport.dataset.y=viewport.style.getPropertyValue('--network-y').replace('px','')||y;window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',stop)}
