function dashboardInvestigations(){return `<section class="investigations-section"><div class="section-head compact"><div><h2>Investigations</h2><p>Select an investigation to open its evidence summary.</p></div></div><div class="investigation-list">${investigations.map((item,index)=>`<article class="panel investigation-card ${index===state.selectedInvestigation?'selected':''}" onclick="openInvestigation(${index})" onkeydown="if(event.key==='Enter'||event.key===' ')openInvestigation(${index})" role="button" tabindex="0"><button class="remove-investigation" type="button" onclick="removeInvestigation(${index},event)" aria-label="Remove ${item.name}">Remove</button><span class="investigation-index">INVESTIGATION ${item.id.slice(-3)}</span><strong>${item.name}</strong><span class="investigation-id">${item.id}</span><span class="tag ${item.statusClass}">${item.status}</span></article>`).join('')}</div><div class="panel create-investigation"><div class="panel-head"><span class="panel-title">Create investigation</span><span class="panel-meta">NEW CASE</span></div><form onsubmit="createInvestigation(event)"><label>Incident name<input name="name" required placeholder="e.g. Krishna Delta Spill"></label><label>Investigation date<input name="date" type="date" required></label><label>Area of interest<input name="area" required placeholder="Select / draw on map, e.g. 16.4°N, 82.1°E"><button class="outline area-picker" type="button" onclick="selectAreaOnMap(this)">⌖ Select / Draw on Map</button></label><fieldset><legend>Data sources</legend><label><input type="checkbox" name="source" value="Sentinel-1" checked> Sentinel-1</label><label><input type="checkbox" name="source" value="Ocean Current" checked> Ocean Current</label><label><input type="checkbox" name="source" value="Wind" checked> Wind</label><label><input type="checkbox" name="source" value="AIS" checked> AIS</label></fieldset><button class="primary" type="submit">＋ Create investigation</button></form></div></section>`}
function dashboardFooter(){return `<footer class="dashboard-footer"><strong>OCEANEYE</strong><span>MARINE INTELLIGENCE</span><h2>FROM DETECTION TO EVIDENCE.</h2><blockquote>“The ocean leaves clues. OceanEye connects them.”</blockquote><p>An AI-powered marine investigation platform that combines satellite imagery, ocean conditions and vessel movement data to detect oil spills, reconstruct their movement, estimate probable source regions, and provide explainable evidence for investigators.</p><small>Smart India Hackathon 2026 Prototype • AI-Powered Marine Oil-Spill Investigation</small></footer>`}
function createInvestigation(event){event.preventDefault();const form=event.currentTarget,formData=new FormData(form),name=formData.get('name'),date=formData.get('date'),area=formData.get('area'),sources=formData.getAll('source');if(!sources.length){toast('Select at least one data source');return}const number=Math.max(...investigations.map(item=>Number(item.id.slice(-3))),0)+1,id='OCEAN-INV-'+String(number).padStart(3,'0'),vesselName='Demo Horizon '+String(number).padStart(2,'0'),item={name,id,status:'Active',statusClass:'active',location:area,date:date+' · 12:00 UTC',areaOfInterest:area,dataSources:sources,confidence:'86.4%',area:'9.4 km²',source:area+' ±5.2 km',vessel:vesselName+' · IMO 9900'+number,ais:'78.2% correlation · 12.6 km from source',drift:'Modeling in progress · 18 hour window',progress:'New investigation · 12% complete',areaChange:'Initial acquisition pass',confidenceNote:'Preliminary confidence · demo',nearby:'04',candidates:'2',lastRun:'Not yet run',correlationState:'4 vessels staged',progressShort:'Acquisition queued',classification:'Preliminary SAR result',lookalike:'pending',cloud:'8%',lookalikeResult:'PENDING',classificationText:'New investigation awaiting source imagery and validation.',candidateScore:'78.2%',vesselType:'Tanker',imo:'9900'+number,vesselDistance:'12.6 km',driftWindow:'18 HOUR BACKTRACK',driftDistance:'18.4 km',conditions:'1.4 kn · NE / 10 kn · W',uncertainty:'±5.2 km',aisWindow:'RADIUS 50 KM · ±10 H',sourceConfidence:'71%',sourceTime:date+' · 06:30 UTC',evidence:'Initial case created from the selected area and data sources.',progressPercent:12,trajectorySeed:number,satellites:sources.includes('Sentinel-1')?[['Sentinel-1 new pass','C-band SAR',date,area,'Ready'],['Sentinel-2 supporting pass','Multispectral MSI',date,area,'Ready']]:[['Ocean observation pass','Optical sensor',date,area,'Ready'],['Coastal reference pass','Multispectral sensor',date,area,'Ready']],missingAis:[['Vessel position','12:15 UTC'],['AIS timestamp','12:20 UTC']],vessels:[{name:vesselName,mmsi:'41900'+number,imo:'9900'+number,type:'Tanker',speed:'10.4 kn',heading:'272°',distance:'12.6 km',delta:'+00:38 h',trajectory:'78%',score:'78.2%',rank:1,match:'High'}]};investigations.push(item);state.selectedInvestigation=investigations.length-1;state.view='investigation';location.hash='investigation/'+id.slice(-3);render()}
function removeInvestigation(index,event){event?.stopPropagation();const item=investigations[index];if(!item||!window.confirm(`REMOVE INVESTIGATION?\n\nAre you sure you want to remove:\n${item.name}\n${item.id}\n\nThis will remove all data associated with this investigation.`))return;const wasOpen=state.view==='investigation'&&state.selectedInvestigation===index;investigations.splice(index,1);state.selectedAisVessel=null;state.selectedVessel=0;if(!investigations.length){state.selectedInvestigation=0}else if(index<state.selectedInvestigation){state.selectedInvestigation-=1}else{state.selectedInvestigation=Math.min(state.selectedInvestigation,investigations.length-1)}if(wasOpen||state.view==='investigation'){state.view='dashboard';location.hash='dashboard'}render()}
function addDetailRemoveAction(){const header=document.querySelector('.investigation-page .section-head');if(!header||header.querySelector('.detail-remove-investigation'))return;const button=document.createElement('button');button.className='remove-investigation detail-remove-investigation';button.type='button';button.textContent='Remove investigation';button.onclick=event=>removeInvestigation(state.selectedInvestigation,event);header.appendChild(button)}
function selectAreaOnMap(button){const input=button.parentElement.querySelector('input[name="area"]');input.value='16.4200°N, 82.1800°E';toast('Demo area selected on map')}
function selectInvestigation(index){state.selectedInvestigation=index;render()}
function openInvestigation(index){state.selectedInvestigation=index;state.view='investigation';location.hash='investigation/'+investigations[index].id.slice(-3);render()}
function backToDashboard(){state.view='dashboard';location.hash='dashboard';render()}
function investigationMap(item){return legacyGlobeMap().replace('17 APR 2026 · 14:30 UTC · 12.48°N 78.21°E',item.date.toUpperCase()+' · '+item.location).replace(/18\.6 km²/gi,item.area).replace(/12\.4821°N · 78\.2145°E/g,item.location).replace(/12\.4821°N/g,item.location).replace(/SPILL · 12\.4821°N/g,'SPILL · '+item.location).replace(/94\.2%/g,item.confidence)}
function investigationMetrics(item){return `<div class="metrics"><div class="metric"><div class="metric-label">DETECTED SPILL AREA</div><div class="metric-value">${item.area}</div><div class="metric-sub">${item.areaChange}</div></div><div class="metric"><div class="metric-label">DETECTION CONFIDENCE</div><div class="metric-value">${item.confidence}</div><div class="metric-sub">${item.confidenceNote}</div></div><div class="metric"><div class="metric-label">NEARBY VESSELS</div><div class="metric-value">${item.nearby}</div><div class="metric-sub warning">${item.candidates} candidates ranked</div></div><div class="metric"><div class="metric-label">INVESTIGATION STATUS</div><div class="metric-value" style="font-size:20px">${item.status}</div><div class="metric-sub">${item.lastRun}</div></div></div>`}
function investigationPage(){const item=investigations[state.selectedInvestigation];const candidateName=item.vessel.replace(' · IMO '+item.imo,'');return `<div class="content investigation-page"><div class="section-head"><div><button class="back-button" onclick="backToDashboard()">← Back to Dashboard</button><h2>${item.name}</h2><p>${item.id} · Evidence-led reconstruction across satellite, metocean and AIS sources.</p></div><span class="tag ${item.statusClass}">${item.status}</span></div>${investigationMetrics(item)}<div class="flow"><div class="flow-step done"><span>01 / ACQUISITION</span><strong>Data loaded</strong><em>● Complete</em></div><div class="flow-step done"><span>02 / PREPROCESSING</span><strong>Aligned & cleaned</strong><em>● Complete</em></div><div class="flow-step done"><span>03 / DETECTION</span><strong>Spill segmented</strong><em>● Complete</em></div><div class="flow-step ${item.status==='Under Investigation'?'active':'done'}"><span>04 / CORRELATION</span><strong>${item.correlationState}</strong><em>● ${item.status==='Under Investigation'?'In progress':'Complete'}</em></div><div class="flow-step ${item.status==='Under Investigation'?'active':'done'}"><span>05 / ASSESSMENT</span><strong>${item.progressShort}</strong><em>● ${item.status==='Under Investigation'?'In progress':'Ready'}</em></div></div><div class="grid-main investigation-visual">${investigationMap(item)}<div class="side-stack"><div class="panel confidence"><div class="panel-head" style="margin:-19px -19px 10px"><span class="panel-title">Detection confidence</span><span class="panel-meta">MODEL / DEMO</span></div><div class="confidence-ring" style="--confidence:${item.confidence}"></div><div class="center"><h3>${item.classification}</h3><div class="tiny">Look-alike risk: ${item.lookalike} · Cloud cover: ${item.cloud}</div></div><div class="progress"><span style="width:${item.confidence}"></span></div><div class="tiny">Confidence is an analytical estimate, not proof.</div></div><div class="panel candidate"><div class="panel-head" style="margin:-16px -17px 5px"><span class="panel-title">Leading candidate</span><span class="tag">${item.candidateScore}</span></div><div class="candidate-row"><div class="rank">01</div><div><strong>${candidateName}</strong><div class="detail">${item.vesselType} · IMO ${item.imo}</div></div><div class="score">${item.candidateScore}<small>OVERALL</small></div></div><p class="tiny" style="line-height:1.5">Trajectory passed ${item.vesselDistance} from the estimated source during the reconstructed window.</p></div></div></div><div class="page-grid investigation-sections"><div class="panel detail-card"><div class="panel-head"><span class="panel-title">Spill classification</span><span class="tag classification-pass">✓ LOOK-ALIKE CHECK: ${item.lookalikeResult}</span></div><p>${item.classificationText}</p><div class="stat-line"><span>Estimated area</span><strong>${item.area}</strong></div><div class="stat-line"><span>Detection confidence</span><strong>${item.confidence}</strong></div><div class="stat-line"><span>Spill location</span><strong>${item.location}</strong></div></div><div class="panel detail-card"><div class="panel-head"><span class="panel-title">Drift analysis</span><span class="panel-meta">${item.driftWindow}</span></div><div class="stat-line"><span>Drift distance</span><strong>${item.driftDistance}</strong></div><div class="stat-line"><span>Current / wind</span><strong>${item.conditions}</strong></div><div class="stat-line"><span>Drift status</span><strong>${item.drift}</strong></div><div class="stat-line"><span>Path uncertainty</span><strong>${item.uncertainty}</strong></div></div><div class="panel detail-card"><div class="panel-head"><span class="panel-title">Source estimation</span><span class="tag amber">ANALYTICAL ESTIMATE</span></div><div class="stat-line"><span>Probable source region</span><strong>${item.source}</strong></div><div class="stat-line"><span>Source confidence</span><strong>${item.sourceConfidence}</strong></div><div class="stat-line"><span>Estimated source time</span><strong>${item.sourceTime}</strong></div></div><div class="panel detail-card"><div class="panel-head"><span class="panel-title">AIS correlation</span><span class="panel-meta">${item.aisWindow}</span></div><div class="stat-line"><span>Nearby vessels</span><strong>${item.nearby}</strong></div><div class="stat-line"><span>Candidate vessel</span><strong>${item.vessel}</strong></div><div class="stat-line"><span>Vessel IMO</span><strong>${item.imo}</strong></div><div class="stat-line"><span>AIS correlation</span><strong>${item.ais}</strong></div></div></div><div class="panel detail-card evidence-summary"><div class="panel-head"><span class="panel-title">Evidence and investigation progress</span><span class="tag">${item.progressPercent}% COMPLETE</span></div><p>${item.evidence}</p><div class="progress"><span style="width:${item.progressPercent}%"></span></div><div class="stat-line"><span>Investigation progress</span><strong>${item.progress}</strong></div></div></div>`}
function map(){return legacyGlobeMap()}
function addAcquisitionSubpoints(){const upload=document.querySelector('.upload');if(upload&&!upload.querySelector('.acquisition-subpoints'))upload.insertAdjacentHTML('beforeend','<ul class="acquisition-subpoints"><li>Upload satellite scenes</li><li>Validate supported file formats</li><li>Stage imagery for analysis</li></ul>');const rows=document.querySelectorAll('.data-table tbody tr');const points=[['SAR imagery','Surface anomaly coverage'],['Ocean current vectors','Regional drift inputs'],['Wind direction and speed','Atmospheric drift inputs'],['Vessel positions and tracks','Time-window correlation data']];rows.forEach((row,index)=>{const cell=row.querySelector('td');if(cell&&!cell.querySelector('.acquisition-subpoints')&&points[index])cell.insertAdjacentHTML('beforeend',`<ul class="acquisition-subpoints"><li>${points[index][0]}</li><li>${points[index][1]}</li></ul>`)});const inputs=document.querySelector('.detail-card');if(inputs&&!inputs.querySelector('.card-subpoints'))inputs.insertAdjacentHTML('beforeend','<ul class="acquisition-subpoints card-subpoints"><li>Satellite and environmental sources</li><li>AIS records for vessel correlation</li><li>Normalized timestamps and coverage</li></ul>')}
function removeDetectionBadge(){document.querySelectorAll('.tag').forEach(tag=>{if(tag.textContent.trim()==='DEMO / SIMULATION')tag.remove()})}
function addMissingAisInteraction(){const content=document.querySelector('.content');const item=currentInvestigation();const row=[...content.querySelectorAll('.stat-line')].find(node=>node.textContent.includes('Missing AIS records'));if(!row||row.dataset.missingAisReady)return;row.dataset.missingAisReady='true';row.classList.add('missing-ais-trigger');row.addEventListener('click',event=>{event.stopPropagation();let popup=content.querySelector('.missing-ais-popup');if(!popup){popup=document.createElement('aside');popup.className='acquisition-popup missing-ais-popup';content.appendChild(popup)}popup.innerHTML=`<div class="acquisition-popup-head"><span>MISSING AIS RECORDS</span><button type="button" class="acquisition-popup-close" aria-label="Close missing AIS details">×</button></div><h3>${item.id}</h3><div class="acquisition-popup-fields">${item.missingAis.map(([field,time])=>`<div><span>${field}</span><strong>${time}</strong></div>`).join('')}</div>`;popup.classList.add('open')});content.addEventListener('click',event=>{if(event.target.closest('.acquisition-popup-close'))content.querySelector('.missing-ais-popup')?.remove()})}
function syncEvidenceGraphData(){const item=currentInvestigation(),vessel=item.vessels[0];document.querySelectorAll('.network-node').forEach(node=>{if(node.classList.contains('satellite')){node.querySelector('span').textContent=item.satellites[0][0];node.querySelector('b').textContent=item.confidence}else if(node.classList.contains('spill')){node.querySelector('strong').textContent='Detected oil spill';node.querySelector('span').textContent=item.area+' anomaly';node.querySelector('b').textContent=item.confidence}else if(node.classList.contains('ais')){node.querySelector('strong').textContent='AIS movement';node.querySelector('span').textContent='Reconstructed track';node.querySelector('b').textContent=vessel.score}else if(node.classList.contains('source')){node.querySelector('span').textContent=item.uncertainty+' region';node.querySelector('b').textContent=item.sourceConfidence}else if(node.classList.contains('candidate')){node.querySelector('strong').textContent='Candidate vessel';node.querySelector('span').textContent=vessel.name;node.querySelector('b').textContent=vessel.score}})}
function acquisitionPopup(type){const item=currentInvestigation(),satelliteIndex=type==='satellite2'?1:0,satellite=item.satellites[satelliteIndex];const details={satellite1:[['Satellite',satellite[0]],['Sensor',satellite[1]],['Acquisition time',satellite[2]],['Coverage',satellite[3]],['Data type','Satellite imagery'],['Status',satellite[4]]],satellite2:[['Satellite',satellite[0]],['Sensor',satellite[1]],['Acquisition time',satellite[2]],['Coverage',satellite[3]],['Data type','Satellite imagery'],['Status',satellite[4]]],ocean:[['Source','Bay current field'],['Current field','Regional ocean vectors'],['Timestamp','17 Apr 2026 · 12:00 UTC'],['Coverage area','Bay of Bengal'],['Processing status','Ready']],weather:[['Source','Wind reanalysis'],['Wind conditions',item.conditions.split(' / ')[1]||'14 kn · WNW'],['Timestamp','17 Apr 2026 · 12:00 UTC'],['Coverage area','10–15°N, 76–81°E'],['Processing status','Ready']],ais:[['Source','AIS coastal feed'],['Vessel records',item.nearby+' nearby vessels'],['Time window',item.aisWindow||'RADIUS 60 KM · WINDOW ±12 H'],['Coverage area','150 km radius'],['Processing status','Ready']]}[type]||[];return `<div class="acquisition-popup-head"><span>DATASET DETAILS</span><button type="button" class="acquisition-popup-close" aria-label="Close dataset details">×</button></div><h3>${details[0]?.[1]||'Dataset details'}</h3><div class="acquisition-popup-fields">${details.slice(1).map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join('')}</div>`}
function addAcquisitionInteractions(){const content=document.querySelector('.content');if(!content||content.dataset.acquisitionReady)return;content.dataset.acquisitionReady='true';const current=currentInvestigation(),upload=content.querySelector('.upload');if(upload)upload.dataset.acquisitionType='satellite1';const rows=content.querySelectorAll('.data-table tbody tr');const satellites=current.satellites;if(rows[0]){rows[0].dataset.acquisitionType='satellite1';const second=document.createElement('tr');second.dataset.acquisitionType='satellite2';second.innerHTML=`<td><strong>${satellites[1][0]}</strong><ul class="acquisition-subpoints"><li>${satellites[1][1]}</li><li>Second coverage pass</li></ul></td><td><span class="tag blue">SATELLITE</span></td><td>${satellites[1][2]}</td><td>${satellites[1][3]}</td><td>91 / 100</td><td><span class="tag">${satellites[1][4]}</span></td>`;rows[0].after(second)}['ocean','weather','ais'].forEach((type,index)=>{if(rows[index+1])rows[index+1].dataset.acquisitionType=type});const sources=current.dataSources||['Sentinel-1','Ocean Current','Wind','AIS'];[...content.querySelectorAll('[data-acquisition-type]')].forEach(node=>{const type=node.dataset.acquisitionType;if(type==='satellite1'||type==='satellite2')node.style.display=sources.includes('Sentinel-1')?'':'none';if(type==='ocean')node.style.display=sources.includes('Ocean Current')?'':'none';if(type==='weather')node.style.display=sources.includes('Wind')?'':'none';if(type==='ais')node.style.display=sources.includes('AIS')?'':'none'});content.addEventListener('click',event=>{const close=event.target.closest('.acquisition-popup-close');const item=event.target.closest('[data-acquisition-type]');let popup=content.querySelector('.acquisition-popup');if(close){popup?.remove();content.querySelectorAll('.acquisition-selected').forEach(node=>node.classList.remove('acquisition-selected'));return}if(item){content.querySelectorAll('.acquisition-selected').forEach(node=>node.classList.remove('acquisition-selected'));item.classList.add('acquisition-selected');if(!popup){popup=document.createElement('aside');popup.className='acquisition-popup';content.appendChild(popup)}popup.innerHTML=acquisitionPopup(item.dataset.acquisitionType);popup.classList.add('open');event.stopPropagation();return}if(popup&&!event.target.closest('.acquisition-popup')){popup.remove();content.querySelectorAll('.acquisition-selected').forEach(node=>node.classList.remove('acquisition-selected'))}})}
function aisCorrelationGraph(){const item=currentInvestigation(),vesselList=item.vessels,positions=[[170,315],[270,125],[390,350],[475,105],[110,180]],spillX=610,spillY=225;return `<div class="trajectory-wrap"><div class="trajectory-heading"><div><h3>Vessel positions and spill correlation</h3><p>Tracks converge on the detected spill region within the investigation time window.</p></div><span class="trajectory-note">Arrows indicate movement toward the reconstructed spill region.</span></div><div class="trajectory-plot ais-correlation-map"><svg viewBox="0 0 800 390" role="img" aria-label="Geographic AIS vessel positions and trajectories"><defs><marker id="ais-map-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#d27d22"/></marker></defs><g class="trajectory-grid"><path d="M70 55H755 M70 115H755 M70 175H755 M70 235H755 M70 295H755 M70 355H755 M70 55V355 M207 55V355 M344 55V355 M481 55V355 M618 55V355 M755 55V355"/></g><text x="70" y="378">${item.location.split(',')[1]||'78°E'}</text><text x="700" y="378">EAST</text><text x="22" y="62">NORTH</text><text x="${spillX+12}" y="${spillY-16}" class="spill-label">DETECTED SPILL · ${item.area}</text><circle class="spill-marker" cx="${spillX}" cy="${spillY}" r="9"/><circle cx="${spillX}" cy="${spillY}" r="25" fill="none" stroke="#d27d22" stroke-dasharray="4 5"/>${vesselList.map((v,index)=>{const [x,y]=positions[index%positions.length];const endX=spillX-18-(index%2)*12,endY=spillY+(index-1)*12;return `<path class="trajectory-line vessel-path ais-track-${index}" d="M${x} ${y} C${x+90} ${y+(spillY-y)*.2} ${endX-100} ${endY+(y-spillY)*.2} ${endX} ${endY}" marker-end="url(#ais-map-arrow)"/><circle class="ais-vessel-marker" cx="${x}" cy="${y}" r="7"/><text class="ais-vessel-label" x="${x+10}" y="${y-10}">${String(index+1).padStart(2,'0')} ${v.name}</text>`}).join('')}</svg></div><div class="trajectory-legend"><span><i class="legend-line spill-legend"></i>DETECTED SPILL</span><span><i class="legend-line" style="--legend-color:var(--amber)"></i>VESSEL TRAJECTORY</span><span>01–${String(vesselList.length).padStart(2,'0')} AIS POSITIONS</span></div></div>`}
function ais(){const original=currentInvestigation();return `<div class="content"><div class="section-head"><div><h2>AIS vessel correlation</h2><p>Vessels intersecting the source region and reconstructed time window.</p></div><button class="outline" onclick="toast('AIS data exported as CSV')">⇩ Export CSV</button></div><div class="panel trajectory-panel">${aisCorrelationGraph()}</div><div class="panel" style="margin-top:18px"><div class="panel-head"><span class="panel-title">Correlated vessels · ${original.vessels.length} candidates</span><span class="panel-meta">RADIUS 60 KM · WINDOW ±12 H</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>RANK</th><th>VESSEL</th><th>TYPE</th><th>DISTANCE</th><th>TIME DIFFERENCE</th><th>TRAJECTORY</th><th>SCORE</th></tr></thead><tbody>${original.vessels.map((v,i)=>`<tr class="vessel-entry ${i===state.selectedVessel?'selected-vessel':''}" data-vessel-index="${i}" onclick="selectVessel(${i})" style="cursor:pointer"><td><strong style="color:${i===0?'var(--amber)':'var(--muted)'}">0${v.rank}</strong></td><td><strong>${v.name}</strong><div class="tiny">MMSI ${v.mmsi} · IMO ${v.imo}</div></td><td>${v.type}</td><td>${v.distance}</td><td>${v.delta}</td><td><span class="tag ${i<2?'':'amber'}">${v.trajectory}</span></td><td><strong style="color:var(--cyan)">${v.score}</strong></td></tr>`).join('')}</tbody></table></div></div></div>`}
function aisCorrelationGraph(){const item=currentInvestigation(),vesselsForMap=item.vessels,spillX=615,spillY=230,originX=470,originY=105,positions=[[120,320],[245,285],[350,160],[455,315],[180,120]],shipColors=['#4e9dff','#f6c76a','#67e5ae','#ff7188','#b58cff'];const spillPath=`M${originX} ${originY} C520 135 545 190 570 205 S600 220 ${spillX} ${spillY}`;return `<div class="trajectory-wrap"><div class="trajectory-heading"><div><h3>Maritime AIS + oil-spill trajectory correlation</h3><p>Chronological vessel movement compared with the reconstructed spill drift path.</p></div><span class="trajectory-note">Correlation supports assessment; it does not prove responsibility.</span></div><div class="trajectory-plot ais-correlation-map"><svg viewBox="0 0 800 390" role="img" aria-label="Ship trajectories and oil spill drift trajectory"><defs><marker id="ais-ship-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#4e9dff"/></marker><marker id="ais-spill-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#d27d22"/></marker></defs><g class="trajectory-grid"><path d="M70 55H755 M70 115H755 M70 175H755 M70 235H755 M70 295H755 M70 355H755 M70 55V355 M207 55V355 M344 55V355 M481 55V355 M618 55V355 M755 55V355"/></g><text x="70" y="378">${item.location.split(',')[1]||'78°E'}</text><text x="700" y="378">EAST</text><text x="22" y="62">NORTH</text><path class="spill-trajectory-path" d="${spillPath}" marker-end="url(#ais-spill-arrow)"/><circle class="spill-origin-marker" cx="${originX}" cy="${originY}" r="7"/><text class="spill-label" x="${originX-22}" y="${originY-14}">SPILL ORIGIN · ${item.sourceTime}</text><circle class="spill-marker" cx="${spillX}" cy="${spillY}" r="10"/><circle cx="${spillX}" cy="${spillY}" r="27" fill="none" stroke="#d27d22" stroke-dasharray="4 5"/><text class="spill-label" x="${spillX-5}" y="${spillY+38}">CURRENT SPILL · ${item.area}</text><text class="correlation-label" x="${spillX-92}" y="${spillY-42}">CORRELATION POINT</text>${vesselsForMap.map((v,index)=>{const [x,y]=positions[index%positions.length],midX=x+(spillX-x)*.42,midY=y+(spillY-y)*.42;return `<path class="trajectory-line vessel-path ais-track-${index}" d="M${x} ${y} C${x+55} ${y+(midY-y)*.35} ${midX-35} ${midY-18} ${midX} ${midY} S${spillX-65} ${spillY+(index-1)*12} ${spillX-24} ${spillY+(index-1)*12}" marker-end="url(#ais-ship-arrow)"/><circle class="ais-vessel-marker" cx="${x}" cy="${y}" r="7"/><circle class="ais-intermediate-marker" cx="${midX}" cy="${midY}" r="4"/><text class="ais-vessel-label" x="${x+10}" y="${y-10}">T1 · ${v.name}</text><text class="ais-time-label" x="${midX+7}" y="${midY+4}">T2</text>`}).join('')}</svg></div><div class="trajectory-legend"><span><i class="legend-line" style="--legend-color:#4e9dff"></i>SHIP PATH · T1 → T2 → T3</span><span><i class="legend-line spill-legend"></i>OIL-SPILL PATH · ORIGIN → CURRENT</span><span>SPATIAL / TEMPORAL CORRELATION</span></div></div>`}
function aisCorrelationGraph(){const item=currentInvestigation(),vesselsForMap=item.vessels,selected=state.selectedAisVessel,sourceSelected=selected===0,spillX=615,spillY=230,originX=470,originY=105,positions=[[120,320],[245,285],[350,160],[455,315],[180,120]],spillPath=`M${originX} ${originY} C520 135 545 190 570 205 S600 220 ${spillX} ${spillY}`;return `<div class="trajectory-wrap"><div class="trajectory-heading"><div><h3>Maritime AIS + oil-spill trajectory correlation</h3><p>Chronological vessel movement compared with the reconstructed spill drift path.</p></div><span class="trajectory-note">Correlation supports assessment; it does not prove responsibility.</span></div><div class="trajectory-plot ais-correlation-map"><svg viewBox="0 0 800 390" role="img" aria-label="Ship trajectories and oil spill drift trajectory"><defs><marker id="ais-ship-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#4e9dff"/></marker><marker id="ais-spill-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#d27d22"/></marker></defs><g class="trajectory-grid"><path d="M70 55H755 M70 115H755 M70 175H755 M70 235H755 M70 295H755 M70 355H755 M70 55V355 M207 55V355 M344 55V355 M481 55V355 M618 55V355 M755 55V355"/></g><text x="70" y="378">${item.location.split(',')[1]||'78°E'}</text><text x="700" y="378">EAST</text><text x="22" y="62">NORTH</text><path class="spill-trajectory-path ${sourceSelected?'source-spill-highlight':''}" d="${spillPath}" marker-end="url(#ais-spill-arrow)"/><circle class="spill-origin-marker" cx="${originX}" cy="${originY}" r="7"/><text class="spill-label" x="${originX-22}" y="${originY-14}">SPILL ORIGIN · ${item.sourceTime}</text><circle class="spill-marker" cx="${spillX}" cy="${spillY}" r="10"/><circle cx="${spillX}" cy="${spillY}" r="27" fill="none" stroke="#d27d22" stroke-dasharray="4 5"/><text class="spill-label" x="${spillX-5}" y="${spillY+38}">CURRENT SPILL · ${item.area}</text><text class="correlation-label" x="${spillX-92}" y="${spillY-42}">CORRELATION POINT</text>${vesselsForMap.map((v,index)=>{const [x,y]=positions[index%positions.length],midX=x+(spillX-x)*.42,midY=y+(spillY-y)*.42,classes=`trajectory-line vessel-path ais-track-${index} ${selected===null?'':selected===index?'selected-trajectory':'deemphasized-trajectory'}`;return `<path class="${classes}" d="M${x} ${y} C${x+55} ${y+(midY-y)*.35} ${midX-35} ${midY-18} ${midX} ${midY} S${spillX-65} ${spillY+(index-1)*12} ${spillX-24} ${spillY+(index-1)*12}" marker-end="url(#ais-ship-arrow)"/><circle class="ais-vessel-marker" cx="${x}" cy="${y}" r="7"/><circle class="ais-intermediate-marker" cx="${midX}" cy="${midY}" r="4"/><text class="ais-vessel-label" x="${x+10}" y="${y-10}">T1 · ${v.name}</text><text class="ais-time-label" x="${midX+7}" y="${midY+4}">T2</text>`}).join('')}</svg></div><div class="trajectory-legend"><span><i class="legend-line" style="--legend-color:#4e9dff"></i>SHIP PATH · T1 → T2 → T3</span><span><i class="legend-line spill-legend"></i>OIL-SPILL PATH · ORIGIN → CURRENT</span><span>SPATIAL / TEMPORAL CORRELATION</span></div></div>`}
const baseTrajectoryMap=aisCorrelationGraph;
function aisCorrelationGraph(){const item=currentInvestigation(),seed=item.trajectorySeed||0,variants=[{spill:'M470 105 C520 135 545 190 570 205 S600 220 615 230',starts:['M120 320','M245 285','M350 160']},{spill:'M420 285 C485 270 520 245 555 220 S590 215 615 230',starts:['M105 110','M210 330','M380 95']},{spill:'M520 90 C545 135 570 170 585 205 S605 220 615 230',starts:['M150 280','M300 120','M430 330']}],variant=variants[seed%variants.length];let html=baseTrajectoryMap();html=html.replace('M470 105 C520 135 545 190 570 205 S600 220 615 230',variant.spill);['M120 320','M245 285','M350 160'].forEach((path,index)=>{html=html.replace(path,variant.starts[index])});return html}
function trajectoryGraph(){return aisCorrelationGraph()}
const baseDashboard=dashboard;
dashboard=function(){return `<div class="content dashboard-selection">${dashboardInvestigations()}${dashboardFooter()}</div>`}
function render(){syncInvestigationData();const item=currentInvestigation();document.getElementById('page-title').textContent=state.view==='investigation'?item.name:titles[state.view];const crumb=document.querySelector('.crumb');if(crumb)crumb.textContent='INVESTIGATIONS / '+item.id;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));const pages={dashboard,investigation:investigationPage,acquisition,preprocess,detection,drift,source,ais,ranking,evidence,report};let page=pages[state.view]();if(state.view==='detection'){const scene=document.createElement('div');scene.innerHTML=page;const image=scene.querySelector('.map-canvas');if(image)image.innerHTML='<img src="oil spill1.png" alt="Oil spill scene" style="display:block;width:100%;height:100%;object-fit:cover">';page=scene.innerHTML}if(state.view==='dashboard'){document.getElementById('app').innerHTML=page}else{document.getElementById('app').innerHTML=bindInvestigationData(page)}if(state.view==='investigation')addDetailRemoveAction();if(state.view==='acquisition'){addAcquisitionSubpoints();addAcquisitionInteractions()}if(state.view==='preprocess')addMissingAisInteraction();if(state.view==='evidence')syncEvidenceGraphData();if(state.view==='detection')removeDetectionBadge();initGlobe();initGlobeControls();}
function runInvestigation(){if(state.running)return;state.running=true;toast('Investigation pipeline started');const button=document.querySelector('.primary');if(button){button.disabled=true;button.textContent='◌ Processing…'}let steps=['Loading demo data','Validating inputs','Detecting spill','Reconstructing drift','Correlating AIS','Ranking candidates','Building evidence graph'];let i=0;const timer=setInterval(()=>{toast(steps[i]+'…');i++;if(i===steps.length){clearInterval(timer);state.running=false;toast('Investigation complete · evidence package ready');render()}},650)}
function runPreprocess(){toast('Preprocessing simulation started');setTimeout(()=>toast('Preprocessing complete · 18,542 records aligned'),1600)}
function selectVessel(i){state.selectedVessel=i;state.selectedAisVessel=i;if(state.view==='ais'||state.view==='report'){render()}else{document.querySelectorAll('.vessel-entry').forEach((row,index)=>row.classList.toggle('selected-vessel',index===i));document.querySelectorAll('.ais-track-'+i).forEach(path=>path.classList.add('selected-trajectory'));document.querySelectorAll('.ais-track-'+i).forEach(path=>path.classList.remove('deemphasized-trajectory'))}toast(vessels[i].name+' selected · trajectory loaded')}
function selectSimulationVessel(i){state.selectedVessel=Number(i);render();toast(vessels[state.selectedVessel].name+' simulation loaded')}
function investigationTrajectoryGraph(){const item=currentInvestigation(),selected=state.selectedAisVessel,seed=item.trajectorySeed||0,variants=[{spill:'M470 105 C520 135 545 190 570 205 S600 220 615 230',starts:[[120,320],[245,285],[350,160]]},{spill:'M420 285 C485 270 520 245 555 220 S590 215 615 230',starts:[[105,110],[210,330],[380,95]]},{spill:'M520 90 C545 135 570 170 585 205 S605 220 615 230',starts:[[150,280],[300,120],[430,330]]}],variant=variants[seed%variants.length],sourceSelected=selected===0;return `<div class="trajectory-wrap"><div class="trajectory-heading"><div><h3>Maritime AIS + oil-spill trajectory correlation</h3><p>Chronological vessel movement compared with the reconstructed spill drift path.</p></div><span class="trajectory-note">Correlation supports assessment; it does not prove responsibility.</span></div><div class="trajectory-plot ais-correlation-map"><svg viewBox="0 0 800 390" role="img" aria-label="Ship trajectories and oil spill drift trajectory"><defs><marker id="ais-final-ship-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#4e9dff"/></marker><marker id="ais-final-spill-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#d27d22"/></marker></defs><g class="trajectory-grid"><path d="M70 55H755 M70 115H755 M70 175H755 M70 235H755 M70 295H755 M70 355H755 M70 55V355 M207 55V355 M344 55V355 M481 55V355 M618 55V355 M755 55V355"/></g><text x="70" y="378">${item.location.split(',')[1]||'78°E'}</text><text x="700" y="378">EAST</text><text x="22" y="62">NORTH</text><path class="spill-trajectory-path ${sourceSelected?'source-spill-highlight':''}" d="${variant.spill}" marker-end="url(#ais-final-spill-arrow)"/><circle class="spill-origin-marker" cx="470" cy="105" r="7"/><text class="spill-label" x="448" y="91">SPILL ORIGIN · ${item.sourceTime}</text><circle class="spill-marker" cx="615" cy="230" r="10"/><text class="spill-label" x="610" y="268">CURRENT SPILL · ${item.area}</text><text class="correlation-label" x="523" y="188">CORRELATION POINT</text>${item.vessels.map((v,index)=>{const [x,y]=variant.starts[index%variant.starts.length],isSelected=selected===index;return `<path class="trajectory-line vessel-path ais-track-${index} ${selected===null?'':isSelected?'selected-trajectory':'deemphasized-trajectory'}" d="M${x} ${y} C${x+65} ${y-22} ${520+index*8} ${220+index*7} 591 ${220+(index-1)*10}" marker-end="url(#ais-final-ship-arrow)"/><circle class="ais-vessel-marker" cx="${x}" cy="${y}" r="7"/><text class="ais-vessel-label" x="${x+10}" y="${y-10}">T1 · ${v.name}</text><text class="ais-time-label" x="${x+35}" y="${y+22}">T2</text>`}).join('')}</svg></div><div class="trajectory-legend"><span><i class="legend-line" style="--legend-color:#4e9dff"></i>SHIP PATH · T1 → T2 → T3</span><span><i class="legend-line spill-legend"></i>OIL-SPILL PATH · ORIGIN → CURRENT</span><span>SPATIAL / TEMPORAL CORRELATION</span></div></div>`}
function aisCorrelationGraph(){return investigationTrajectoryGraph()}
function trajectoryGraph(){return investigationTrajectoryGraph()}
function applyHashRoute(){if(!location.hash)return;const match=location.hash.match(/^#investigation\/(\d{3})$/);if(match){const index=investigations.findIndex(item=>item.id.endsWith(match[1]));if(index>=0){state.selectedInvestigation=index;state.view='investigation';return}}const route=location.hash.replace(/^#/,'');const moduleViews=['dashboard','acquisition','preprocess','detection','drift','source','ais','ranking','evidence','report'];if(moduleViews.includes(route))state.view=route}
document.getElementById('nav').addEventListener('click',e=>{const btn=e.target.closest('.nav-item');if(btn){e.preventDefault();e.stopPropagation();state.view=btn.dataset.view;history.replaceState({},'',location.pathname+'#'+state.view);render()}});
applyHashRoute();render();
